#ifndef __CCD_SIMPLEX_H__
#define __CCD_SIMPLEX_H__


#ifdef __cplusplus
extern "C" {
#endif /* __cplusplus */

struct _ccd_simplex_t {
    ccd_support_t ps[4];
    int last; //!< index of last added point
};
typedef struct _ccd_simplex_t ccd_simplex_t;


static __device__ __forceinline__ void ccdSimplexInit(ccd_simplex_t *s);
static __device__ __forceinline__ int ccdSimplexSize(const ccd_simplex_t *s);
static __device__ __forceinline__ const ccd_support_t *ccdSimplexLast(const ccd_simplex_t *s);
static __device__ __forceinline__ const ccd_support_t *ccdSimplexPoint(const ccd_simplex_t *s, int idx);
static __device__ __forceinline__ ccd_support_t *ccdSimplexPointW(ccd_simplex_t *s, int idx);

static __device__ __forceinline__ void ccdSimplexAdd(ccd_simplex_t *s, const ccd_support_t *v);
static __device__ __forceinline__ void ccdSimplexSet(ccd_simplex_t *s, size_t pos, const ccd_support_t *a);
static __device__ __forceinline__ void ccdSimplexSetSize(ccd_simplex_t *s, int size);
static __device__ __forceinline__ void ccdSimplexSwap(ccd_simplex_t *s, size_t pos1, size_t pos2);


/**** INLINES ****/

static __device__ __forceinline__ void ccdSimplexInit(ccd_simplex_t *s)
{
    s->last = -1;
}

static __device__ __forceinline__ int ccdSimplexSize(const ccd_simplex_t *s)
{
    return s->last + 1;
}

static __device__ __forceinline__ const ccd_support_t *ccdSimplexLast(const ccd_simplex_t *s)
{
    return ccdSimplexPoint(s, s->last);
}

static __device__ __forceinline__ const ccd_support_t *ccdSimplexPoint(const ccd_simplex_t *s, int idx)
{
    // here is no check on boundaries
    return &s->ps[idx];
}
static __device__ __forceinline__ ccd_support_t *ccdSimplexPointW(ccd_simplex_t *s, int idx)
{
    return &s->ps[idx];
}

static __device__ __forceinline__ void ccdSimplexAdd(ccd_simplex_t *s, const ccd_support_t *v)
{
    // here is no check on boundaries in sake of speed
    ++s->last;
    ccdSupportCopy(s->ps + s->last, v);
}

static __device__ __forceinline__ void ccdSimplexSet(ccd_simplex_t *s, size_t pos, const ccd_support_t *a)
{
    ccdSupportCopy(s->ps + pos, a);
}

static __device__ __forceinline__ void ccdSimplexSetSize(ccd_simplex_t *s, int size)
{
    s->last = size - 1;
}

static __device__ __forceinline__ void ccdSimplexSwap(ccd_simplex_t *s, size_t pos1, size_t pos2)
{
    ccd_support_t supp;

    ccdSupportCopy(&supp, &s->ps[pos1]);
    ccdSupportCopy(&s->ps[pos1], &s->ps[pos2]);
    ccdSupportCopy(&s->ps[pos2], &supp);
}

#ifdef __cplusplus
} /* extern "C" */
#endif /* __cplusplus */

#endif /* __CCD_SIMPLEX_H__ */


__device__ ccd_vec3_t native_origin = {{0.0,0.0,0.0}};
extern "C" { __device__ ccd_vec3_t* ccd_vec3_origin = &native_origin; }
__device__ int native_mpr_guard(const ccd_t* ccd,int phase) {
 if (++ccd->adapter_diag[phase] > ccd->watchdog) { *ccd->adapter_error=6; return 0; }
 return 1;
}

static __device__ __forceinline__ ccd_real_t __ccdVec3PointSegmentDist2(const ccd_vec3_t *P,
                                                  const ccd_vec3_t *x0,
                                                  const ccd_vec3_t *b,
                                                  ccd_vec3_t *witness)
{
    // The computation comes from solving equation of segment:
    //      S(t) = x0 + t.d
    //          where - x0 is initial point of segment
    //                - d is direction of segment from x0 (|d| > 0)
    //                - t belongs to <0, 1> interval
    // 
    // Than, distance from a segment to some point P can be expressed:
    //      D(t) = |x0 + t.d - P|^2
    //          which is distance from any point on segment. Minimization
    //          of this function brings distance from P to segment.
    // Minimization of D(t) leads to simple quadratic equation that's
    // solving is straightforward.
    //
    // Bonus of this method is witness point for free.

    ccd_real_t dist, t;
    ccd_vec3_t d, a;

    // direction of segment
    ccdVec3Sub2(&d, b, x0);

    // precompute vector from P to x0
    ccdVec3Sub2(&a, x0, P);

    t  = -CCD_REAL(1.) * ccdVec3Dot(&a, &d);
    t /= ccdVec3Len2(&d);

    if (t < CCD_ZERO || ccdIsZero(t)){
        dist = ccdVec3Dist2(x0, P);
        if (witness)
            ccdVec3Copy(witness, x0);
    }else if (t > CCD_ONE || ccdEq(t, CCD_ONE)){
        dist = ccdVec3Dist2(b, P);
        if (witness)
            ccdVec3Copy(witness, b);
    }else{
        if (witness){
            ccdVec3Copy(witness, &d);
            ccdVec3Scale(witness, t);
            ccdVec3Add(witness, x0);
            dist = ccdVec3Dist2(witness, P);
        }else{
            // recycling variables
            ccdVec3Scale(&d, t);
            ccdVec3Add(&d, &a);
            dist = ccdVec3Len2(&d);
        }
    }

    return dist;
}

__device__ ccd_real_t ccdVec3PointSegmentDist2(const ccd_vec3_t *P,
                                    const ccd_vec3_t *x0, const ccd_vec3_t *b,
                                    ccd_vec3_t *witness)
{
    return __ccdVec3PointSegmentDist2(P, x0, b, witness);
}

__device__ ccd_real_t ccdVec3PointTriDist2(const ccd_vec3_t *P,
                                const ccd_vec3_t *x0, const ccd_vec3_t *B,
                                const ccd_vec3_t *C,
                                ccd_vec3_t *witness)
{
    // Computation comes from analytic expression for triangle (x0, B, C)
    //      T(s, t) = x0 + s.d1 + t.d2, where d1 = B - x0 and d2 = C - x0 and
    // Then equation for distance is:
    //      D(s, t) = | T(s, t) - P |^2
    // This leads to minimization of quadratic function of two variables.
    // The solution from is taken only if s is between 0 and 1, t is
    // between 0 and 1 and t + s < 1, otherwise distance from segment is
    // computed.

    ccd_vec3_t d1, d2, a;
    ccd_real_t u, v, w, p, q, r, d;
    ccd_real_t s, t, dist, dist2;
    ccd_vec3_t witness2;

    ccdVec3Sub2(&d1, B, x0);
    ccdVec3Sub2(&d2, C, x0);
    ccdVec3Sub2(&a, x0, P);

    u = ccdVec3Dot(&a, &a);
    v = ccdVec3Dot(&d1, &d1);
    w = ccdVec3Dot(&d2, &d2);
    p = ccdVec3Dot(&a, &d1);
    q = ccdVec3Dot(&a, &d2);
    r = ccdVec3Dot(&d1, &d2);

    d = w * v - r * r;
    if (ccdIsZero(d)){
        // To avoid division by zero for zero (or near zero) area triangles
        s = t = -1.;
    }else{
        s = (q * r - w * p) / d;
        t = (-s * r - q) / w;
    }

    if ((ccdIsZero(s) || s > CCD_ZERO)
            && (ccdEq(s, CCD_ONE) || s < CCD_ONE)
            && (ccdIsZero(t) || t > CCD_ZERO)
            && (ccdEq(t, CCD_ONE) || t < CCD_ONE)
            && (ccdEq(t + s, CCD_ONE) || t + s < CCD_ONE)){

        if (witness){
            ccdVec3Scale(&d1, s);
            ccdVec3Scale(&d2, t);
            ccdVec3Copy(witness, x0);
            ccdVec3Add(witness, &d1);
            ccdVec3Add(witness, &d2);

            dist = ccdVec3Dist2(witness, P);
        }else{
            dist  = s * s * v;
            dist += t * t * w;
            dist += CCD_REAL(2.) * s * t * r;
            dist += CCD_REAL(2.) * s * p;
            dist += CCD_REAL(2.) * t * q;
            dist += u;
        }
    }else{
        dist = __ccdVec3PointSegmentDist2(P, x0, B, witness);

        dist2 = __ccdVec3PointSegmentDist2(P, x0, C, &witness2);
        if (dist2 < dist){
            dist = dist2;
            if (witness)
                ccdVec3Copy(witness, &witness2);
        }

        dist2 = __ccdVec3PointSegmentDist2(P, B, C, &witness2);
        if (dist2 < dist){
            dist = dist2;
            if (witness)
                ccdVec3Copy(witness, &witness2);
        }
    }

    return dist;
}

__device__ void ccdFirstDirDefault(const void *o1, const void *o2, ccd_vec3_t *dir)
{
    ccdVec3Set(dir, CCD_ONE, CCD_ZERO, CCD_ZERO);
}
/***
