static __device__ int mjc_ellipsoidOutside(mjtNum nrm[3], const mjtNum pos[3], const mjtNum size[3]);
__device__ void mjc_fixNormal(const mjModel* m, const mjData* d, mjContact* con, int g1, int g2);
