static __device__ void mju_rotateFrame(const mjtNum origin[3], const mjtNum rot[9],
                            mjtNum xmat[9], mjtNum xpos[3]);
__device__ int mjc_Convex(const mjModel* m, const mjData* d,
               mjContact* con, int g1, int g2, mjtNum margin);
__device__ void mjccd_center(const void *obj, ccd_vec3_t *center) {
  const mjtCCD* ccd = (const mjtCCD*)obj;

  // return geom position
  mju_copy3(center->v, ccd->data->geom_xpos + 3*ccd->geom);
}
// Stable argmax uses the original scan ordinal, not vertex/global ID, as its
// tie breaker. All lanes in this query subgroup enter every shuffle.
static __device__ __forceinline__ unsigned native_query_mask(int width) {
  const int first=(int(threadIdx.x)&31)&~(width-1);
  return (0xffffffffu>>(32-width))<<first;
}
static __device__ __forceinline__ void native_query_argmax(
    double& value,int& ordinal,int width,unsigned mask) {
  const int lane=int(threadIdx.x)&(width-1);
  for(int delta=width/2;delta;delta>>=1){
    const double other=__shfl_down_sync(mask,value,delta,width);
    const int index=__shfl_down_sync(mask,ordinal,delta,width);
    if(lane+delta<width && index>=0 &&
       (ordinal<0 || other>value || (other==value && index<ordinal))){value=other;ordinal=index;}
  }
  value=__shfl_sync(mask,value,0,width);
  ordinal=__shfl_sync(mask,ordinal,0,width);
}
// Cooperative AoS tile read: three contiguous float runs are loaded by the
// subgroup, then routed to the lane owning the original vertex ordinal.
// Shuffles preserve float bits; conversion to mjtNum stays at the dot product.
// No full-mesh mirror or shared query/contact allocation is introduced.
static __device__ __forceinline__ void native_mesh_vertex_tile(
    const float* vertices,int base,int n,int width,unsigned mask,float* xyz) {
  const int lane=int(threadIdx.x)&(width-1);
  // Each active packet contains exactly four contiguous floats. The scalar
  // tail handles incomplete packets without reading the next vertex/model.
  float fields[4];
  const int available=3*(n-base),offset=4*lane;
  if(offset+3<available && offset+3<3*width && libero_vec::aligned16(vertices+3*base+offset)){
    const float4 v=*reinterpret_cast<const float4*>(vertices+3*base+offset);
    fields[0]=v.x;fields[1]=v.y;fields[2]=v.z;fields[3]=v.w;
  }else{
    for(int r=0;r<4;++r)fields[r]=(offset+r<available && offset+r<3*width)?vertices[3*base+offset+r]:0.0f;
  }
  for(int h=0;h<3;++h){
    const int ordinal=3*lane+h,source=ordinal/4,field=ordinal%4;
    const float a=__shfl_sync(mask,fields[0],source,width);
    const float b=__shfl_sync(mask,fields[1],source,width);
    const float c=__shfl_sync(mask,fields[2],source,width);
    const float d=__shfl_sync(mask,fields[3],source,width);
    xyz[h]=field==0?a:(field==1?b:(field==2?c:d));
  }
}
static __device__ int native_mesh_support_group(const mjtCCD* ccd,const double* dir) {
  const mjModel* m=ccd->model;const int width=m->adapter_subgroup_width;
  const unsigned mask=native_query_mask(width);
  const int lane=int(threadIdx.x)&(width-1),id=m->geom_dataid[ccd->geom];
  const float* vertices=m->mesh_vert+3*m->mesh_vertadr[id];
  const int graphadr=m->mesh_graphadr[id];
  int best=-1;double value=-1E+10;
  if(graphadr<0){
    const int n=m->mesh_vertnum[id];
    for(int base=0;base<n;base+=width){
      float xyz[3];native_mesh_vertex_tile(vertices,base,n,width,mask,xyz);
      const int i=base+lane;
      if(i<n){
        const double dot=dir[0]*(mjtNum)xyz[0]+dir[1]*(mjtNum)xyz[1]+dir[2]*(mjtNum)xyz[2];
        if(dot>value){value=dot;best=i;}
      }
    }
    native_query_argmax(value,best,width,mask);
    ((mjtCCD*)ccd)->meshindex=best;return best;
  }
  const int nv=m->mesh_graph[graphadr];
  const int* edgeadr=m->mesh_graph+graphadr+2;
  const int* globalid=edgeadr+nv;const int* edges=globalid+nv;
  best=0;
  value=dir[0]*(mjtNum)vertices[3*globalid[0]]+
        dir[1]*(mjtNum)vertices[3*globalid[0]+1]+dir[2]*(mjtNum)vertices[3*globalid[0]+2];
  int steps=0;
  while(true){
    if(++steps>m->watchdog){*m->adapter_error=6;return -2;}
    // Freeze the current vertex's original adjacency list. The upstream
    // loop changes best while visiting this same list, then starts a new list.
    const int start=edgeadr[best];int end=start;
    // One lane finds the same original sentinel; do not prefetch beyond it.
    if(lane==0){
      if(m->mesh_edge_end)end=m->mesh_edge_end[graphadr+2+best];
      else while(edges[end]>=0)++end;
    }
    end=__shfl_sync(mask,end,0,width);
    double candidate=value;int ordinal=-1;
    for(int i=start+lane;i<end;i+=width){
      const int vertex=globalid[edges[i]];
      const double dot=dir[0]*(mjtNum)vertices[3*vertex]+dir[1]*(mjtNum)vertices[3*vertex+1]+dir[2]*(mjtNum)vertices[3*vertex+2];
      if(dot>candidate){candidate=dot;ordinal=i;}
    }
    native_query_argmax(candidate,ordinal,width,mask);
    if(ordinal<0)break;
    best=edges[ordinal];value=candidate;
  }
  ((mjtCCD*)ccd)->meshindex=best;return globalid[best];
}
__device__ void mjccd_support(const void *obj, const ccd_vec3_t *_dir, ccd_vec3_t *vec) {
  const mjtCCD* ccd = (const mjtCCD*)obj;
  const mjModel* m = ccd->model;
  const mjData* d = ccd->data;
  int g = ccd->geom;

  float* vertdata;
  int ibest, graphadr, numvert, change, locid;
  int *vert_edgeadr, *vert_globalid, *edge_localid;
  mjtNum tmp, vdot;

  const mjtNum* size = m->geom_size+3*g;  // geom sizes
  mjtNum dir[3];                          // direction in geom local frame
  mjtNum res[3];                          // result in geom local frame

  // rotate dir to geom local frame
  mju_rotVecMatT(dir, _dir->v, d->geom_xmat+9*g);

  // compute result according to geom type
  switch (m->geom_type[g]) {
  case mjGEOM_SPHERE:
    mju_scl3(res, dir, size[0]);
    break;

  case mjGEOM_CAPSULE:
    // start with sphere
    mju_scl3(res, dir, size[0]);

    // add cylinder contribution
    res[2] += mju_sign(dir[2]) * size[1];
    break;

  case mjGEOM_ELLIPSOID:
    // find support point on unit sphere: scale dir by ellipsoid sizes and renormalize
    for (int i=0; i < 3; i++) {
      res[i] = dir[i] * size[i];
    }
    mju_normalize3(res);

    // transform to ellipsoid
    for (int i=0; i < 3; i++) {
      res[i] *= size[i];
    }
    break;

  case mjGEOM_CYLINDER:
    // set result in XY plane: support on circle
    tmp = mju_sqrt(dir[0]*dir[0] + dir[1]*dir[1]);
    if (tmp > mjMINVAL) {
      res[0] = dir[0]/tmp*size[0];
      res[1] = dir[1]/tmp*size[0];
    } else {
      res[0] = res[1] = 0;
    }

    // set result in Z direction
    res[2] = mju_sign(dir[2]) * size[1];
    break;

  case mjGEOM_BOX:
    for (int i=0; i < 3; i++) {
      res[i] = mju_sign(dir[i]) * size[i];
    }
    break;

  case mjGEOM_MESH:
    // Reuse only an exact local direction. Source vertex/adjacency tie rules
    // are retained because every miss executes the original search below.
    if(native_support_reuse_get(&((mjtCCD*)ccd)->support_reuse,dir,res,
                               &((mjtCCD*)ccd)->meshindex))break;
    if(m->adapter_subgroup_width==8 || m->adapter_subgroup_width==16 || m->adapter_subgroup_width==32){
      ibest=native_mesh_support_group(ccd,dir);
      if(ibest==-2){mju_zero3(vec->v);return;}
      if(ibest<0){*m->adapter_error=7;mju_zero3(res);}
      else{
        vertdata=m->mesh_vert+3*m->mesh_vertadr[m->geom_dataid[g]];
        for(int i=0;i<3;++i)res[i]=(mjtNum)vertdata[3*ibest+i];
      }
      if(*m->adapter_error==0)
        native_support_reuse_put(&((mjtCCD*)ccd)->support_reuse,dir,res,ccd->meshindex);
      break;
    }
    // init search
    vertdata = m->mesh_vert + 3*m->mesh_vertadr[m->geom_dataid[g]];
    tmp = -1E+10;
    ibest = -1;

    // no graph data: exhaustive search
    if (m->mesh_graphadr[m->geom_dataid[g]] < 0) {
      // search all vertices, find best
      for (int i=0; i < m->mesh_vertnum[m->geom_dataid[g]]; i++) {
        // vdot = dot(vertex, dir)
        vdot = dir[0] * (mjtNum)vertdata[3*i] +
               dir[1] * (mjtNum)vertdata[3*i+1] +
               dir[2] * (mjtNum)vertdata[3*i+2];

        // update best
        if (vdot > tmp) {
          tmp = vdot;
          ibest = i;
        }
      }

      // record best vertex index, in globalid format
      ((mjtCCD*)ccd)->meshindex = ibest;
    }

    // hill-climb using graph data
    else {
      // get info
      graphadr = m->mesh_graphadr[m->geom_dataid[g]];
      numvert = m->mesh_graph[graphadr];
      vert_edgeadr = m->mesh_graph + graphadr + 2;
      vert_globalid = m->mesh_graph + graphadr + 2 + numvert;
      edge_localid = m->mesh_graph + graphadr + 2 + 2*numvert;

      // init with first vertex in convex hull
      ibest = 0;
      tmp = dir[0] * (mjtNum)vertdata[3*vert_globalid[0]] +
            dir[1] * (mjtNum)vertdata[3*vert_globalid[0]+1] +
            dir[2] * (mjtNum)vertdata[3*vert_globalid[0]+2];

      // hill-climb until no change
      change = 1;
      int adapter_steps=0;
      while (change) {
        if (++adapter_steps > m->watchdog) { *m->adapter_error=6; mju_zero3(vec->v); return; }
        // look for improvement in ibest neighborhood
        change = 0;
        int i = vert_edgeadr[ibest];
        while ((locid=edge_localid[i]) >= 0) {
          // vdot = dot(vertex, dir)
          vdot = dir[0] * (mjtNum)vertdata[3*vert_globalid[locid]] +
                 dir[1] * (mjtNum)vertdata[3*vert_globalid[locid]+1] +
                 dir[2] * (mjtNum)vertdata[3*vert_globalid[locid]+2];

          // update best
          if (vdot > tmp) {
            tmp = vdot;
            ibest = locid;
            change = 1;
          }

          // advance to next edge
          i++;
        }
      }

      // record best vertex index, in locid format
      ((mjtCCD*)ccd)->meshindex = ibest;

      // map best index to globalid
      ibest = vert_globalid[ibest];
    }

    // sanity check, SHOULD NOT OCCUR
    if (ibest < 0) {
      *m->adapter_error=7;
      mju_zero3(res);
    }

    // copy best vertex
    else {
      for (int i=0; i < 3; i++) {
        res[i] = (mjtNum)vertdata[3*ibest + i];
      }
    }
    if(*m->adapter_error==0)
      native_support_reuse_put(&((mjtCCD*)ccd)->support_reuse,dir,res,ccd->meshindex);
    break;

  default:
    *m->adapter_error=4; mju_zero3(res);
  }

  // add dir*margin/2 to result
  for (int i=0; i < 3; i++) {
    res[i] += dir[i] * ccd->margin/2;
  }

  // rotate result to global frame
  mju_rotVecMat(vec->v, res, d->geom_xmat+9*g);

  // add geom position
  mju_addTo3(vec->v, d->geom_xpos+3*g);
}
static __device__ int mjc_ellipsoidInside(mjtNum nrm[3], const mjtNum pos[3], const mjtNum size[3]) {
  // algorithm constants
  const int maxiter = 30;
  const mjtNum tolerance = 1e-6;

  // precompute quantities
  mjtNum S2inv[3] = {1/(size[0]*size[0]), 1/(size[1]*size[1]), 1/(size[2]*size[2])};
  mjtNum C = pos[0]*pos[0]*S2inv[0] + pos[1]*pos[1]*S2inv[1] + pos[2]*pos[2]*S2inv[2] - 1;
  if (C > 0) {
    return 0;
  }

  // normalize initial normal (just in case)
  mju_normalize3(nrm);

  // main iteration
  int iter;
  for (iter=0; iter < maxiter; iter++) {
    // coefficients and determinant of quadratic
    mjtNum A = nrm[0]*nrm[0]*S2inv[0] + nrm[1]*nrm[1]*S2inv[1] + nrm[2]*nrm[2]*S2inv[2];
    mjtNum B = pos[0]*nrm[0]*S2inv[0] + pos[1]*nrm[1]*S2inv[1] + pos[2]*nrm[2]*S2inv[2];
    mjtNum det = B*B - A*C;
    if (det < mjMINVAL || A < mjMINVAL) {
      return (iter > 0);
    }

    // ray intersection with ellipse: pos + x*nrm, x>=0
    mjtNum x = (-B + mju_sqrt(det))/A;
    if (x < 0) {
      return (iter > 0);
    }

    // new point on ellipsoid
    mjtNum pnt[3];
    mju_addScl3(pnt, pos, nrm, x);

    // normal at new point
    mjtNum newnrm[3] = {pnt[0]*S2inv[0], pnt[1]*S2inv[1], pnt[2]*S2inv[2]};
    mju_normalize3(newnrm);

    // save change and assign
    mjtNum change = mju_dist3(nrm, newnrm);
    mju_copy3(nrm, newnrm);

    // terminate if converged
    if (change < tolerance) {
      break;
    }
  }

  return 1;
}
static __device__ int mjc_ellipsoidOutside(mjtNum nrm[3], const mjtNum pos[3], const mjtNum size[3]) {
  // algorithm constants
  const int maxiter = 30;
  const mjtNum tolerance = 1e-6;

  // precompute quantities
  mjtNum S2[3] = {size[0]*size[0], size[1]*size[1], size[2]*size[2]};
  mjtNum PS2[3] = {pos[0]*pos[0]*S2[0], pos[1]*pos[1]*S2[1], pos[2]*pos[2]*S2[2]};

  // main iteration
  mjtNum la = 0;
  int iter;
  for (iter=0; iter < maxiter; iter++) {
    // precompute 1/(s^2+la)
    mjtNum R[3] = {1/(S2[0]+la), 1/(S2[1]+la), 1/(S2[2]+la)};

    // value
    mjtNum val = PS2[0]*R[0]*R[0] + PS2[1]*R[1]*R[1] + PS2[2]*R[2]*R[2] - 1;
    if (val < tolerance) {
      break;
    }

    // derivative
    mjtNum deriv = -2*(PS2[0]*R[0]*R[0]*R[0] + PS2[1]*R[1]*R[1]*R[1] + PS2[2]*R[2]*R[2]*R[2]);
    if (deriv > -mjMINVAL) {
      break;
    }

    // delta
    mjtNum delta = -val/deriv;
    if (delta < tolerance) {
      break;
    }

    // update
    la += delta;
  }

  // compute normal given lambda
  nrm[0] = pos[0]/(S2[0]+la);
  nrm[1] = pos[1]/(S2[1]+la);
  nrm[2] = pos[2]/(S2[2]+la);
  mju_normalize3(nrm);

  return 1;
}
__device__ void mjc_fixNormal(const mjModel* m, const mjData* d, mjContact* con, int g1, int g2) {
  mjtNum dst1, dst2;

  // get geom ids and types
  int gid[2] = {g1, g2};
  int type[2];
  for (int i=0; i < 2; i++) {
    type[i] = m->geom_type[gid[i]];

    // set to -1 if type cannot be processed
    if (type[i] != mjGEOM_SPHERE    &&
        type[i] != mjGEOM_CAPSULE   &&
        type[i] != mjGEOM_ELLIPSOID &&
        type[i] != mjGEOM_CYLINDER) {
      type[i] = -1;
    }
  }

  // neither type can be processed: nothing to do
  if (type[0] < 0 && type[1] < 0) {
    return;
  }

  // init normals
  mjtNum normal[2][3] = {
    {con->frame[0], con->frame[1], con->frame[2]},
    {-con->frame[0], -con->frame[1], -con->frame[2]}
  };

  // process geoms in type range
  int processed[2] = {0, 0};
  for (int i=0; i < 2; i++) {
    if (type[i] >= 0) {
      // get geom mat and size
      mjtNum* mat = d->geom_xmat + 9*gid[i];
      mjtNum* size = m->geom_size + 3*gid[i];

      // map contact point and normal to local frame
      mjtNum dif[3], pos[3], nrm[3];
      mju_sub3(dif, con->pos, d->geom_xpos+3*gid[i]);
      mju_rotVecMatT(pos, dif, mat);
      mju_rotVecMatT(nrm, normal[i], mat);

      // process according to type
      switch (type[i]) {
      case mjGEOM_SPHERE:
        mju_copy3(nrm, pos);
        processed[i] = 1;
        break;

      case mjGEOM_CAPSULE:
        // Z: bottom cap
        if (pos[2] < -size[1]) {
          nrm[2] = pos[2]+size[1];
        }

        // Z: top cap
        else if (pos[2] > size[1]) {
          nrm[2] = pos[2]-size[1];
        }

        // Z: cylinder
        else {
          nrm[2] = 0;
        }

        // copy XY
        nrm[0] = pos[0];
        nrm[1] = pos[1];
        processed[i] = 1;
        break;

      case mjGEOM_ELLIPSOID:
        // guard against invalid ellipsoid size (just in case)
        if (size[0] < mjMINVAL || size[1] < mjMINVAL || size[2] < mjMINVAL) {
          break;
        }

        // compute elliptic distance^2
        dst1 = pos[0]*pos[0]/(size[0]*size[0]) +
               pos[1]*pos[1]/(size[1]*size[1]) +
               pos[2]*pos[2]/(size[2]*size[2]);

        // dispatch to inside or outside solver
        if (dst1 <= 1) {
          processed[i] = mjc_ellipsoidInside(nrm, pos, size);
        } else {
          processed[i] = mjc_ellipsoidOutside(nrm, pos, size);
        }
        break;

      case mjGEOM_CYLINDER:
        // skip if within 5% length of flat wall
        if (mju_abs(pos[2]) > 0.95*size[1]) {
          break;
        }

        // compute distances to flat and round wall
        dst1 = mju_abs(size[1]-mju_abs(pos[2]));
        dst2 = mju_abs(size[0]-mju_norm(pos, 2));

        // require 4x closer to round than flat wall
        if (dst1 < 0.25*dst2) {
          break;
        }

        // set normal for round wall
        nrm[0] = pos[0];
        nrm[1] = pos[1];
        nrm[2] = 0;
        processed[i] = 1;
        break;
      }

      // normalize and map normal to global frame
      if (processed[i]) {
        mju_normalize3(nrm);
        mju_rotVecMat(normal[i], nrm, mat);
      }
    }
  }

  // both processed: average
  if (processed[0] && processed[1]) {
    mju_sub3(con->frame, normal[0], normal[1]);
    mju_normalize3(con->frame);
  }

  // first processed: copy
  else if (processed[0]) {
    mju_copy3(con->frame, normal[0]);
  }

  // second processed: copy reverse
  else if (processed[1]) {
    mju_scl3(con->frame, normal[1], -1);
  }

  // clear second frame axis if processed, just in case
  if (processed[0] || processed[1]) {
    mju_zero3(con->frame+3);
  }
}
static __device__ int mjc_MPRIteration(mjtCCD* obj1, mjtCCD* obj2, const ccd_t* ccd,
                            const mjModel* m, const mjData* d,
                            mjContact* con, int g1, int g2, mjtNum margin) {
  ccd_vec3_t dir, pos;
  ccd_real_t depth;
  if (ccdMPRPenetration(obj1, obj2, ccd, &depth, &dir, &pos) == 0) {
    // contact is found but normal is undefined
    if (ccdVec3Eq(&dir, ccd_vec3_origin)) {
      return 0;
    }

    // fill in contact data
    con->dist = margin-depth;
    mju_copy3(con->frame, dir.v);
    mju_copy3(con->pos, pos.v);
    mju_zero3(con->frame+3);

    // fix contact frame normal
    mjc_fixNormal(m, d, con, g1, g2);

    return 1;
  }

  // no contact found
  else {
    return 0;
  }
}
static __device__ int mjc_isDistinctContact(mjContact* con, int ncon, mjtNum tolerance) {
  for (int i=0; i < ncon-1; i++) {
    if (mju_dist3(con[i].pos, con[ncon - 1].pos) <= tolerance) {
      return 0;
    }
  }
  return 1;
}
static __device__ void mju_rotateFrame(const mjtNum origin[3], const mjtNum rot[9],
                            mjtNum xmat[9], mjtNum xpos[3]) {
  mjtNum mat[9], vec[3], rel[3];

  // rotate frame: xmat = rot*xmat
  mju_mulMatMat(mat, rot, xmat, 3, 3, 3);
  mju_copy(xmat, mat, 9);

  // vector to rotation origin: rel = origin - xpos
  mju_sub3(rel, origin, xpos);

  // displacement of origin due to rotation: vec = rot*rel - rel
  mju_rotVecMat(vec, rel, rot);
  mju_subFrom3(vec, rel);

  // correct xpos by subtracting displacement: xpos = xpos - vec
  mju_subFrom3(xpos, vec);
}
__device__ int mjc_Convex(const mjModel* m, const mjData* d,
               mjContact* con, int g1, int g2, mjtNum margin) {
  ccd_t ccd;
  ccd.adapter_error=m->adapter_error; ccd.adapter_diag=m->adapter_diag; ccd.watchdog=m->watchdog;
  mjtCCD obj1 = {m, d, g1, -1, margin, {1, 0, 0, 0}};
  mjtCCD obj2 = {m, d, g2, -1, margin, {1, 0, 0, 0}};

  // init ccd structure
  ccd.first_dir = ccdFirstDirDefault;
  ccd.center1 = mjccd_center;
  ccd.center2 = mjccd_center;
  ccd.support1 = mjccd_support;
  ccd.support2 = mjccd_support;

  // set ccd paramters
  ccd.max_iterations = m->opt.mpr_iterations;
  ccd.mpr_tolerance = m->opt.mpr_tolerance;

  // find initial contact
  int ncon = mjc_MPRIteration(&obj1, &obj2, &ccd, m, d, con, g1, g2, margin);

  // look for additional contacts
  if (ncon && mjENABLED(mjENBL_MULTICCD)  // TODO(tassa) leave as bitflag or make geom attribute (?)
      && m->geom_type[g1] != mjGEOM_ELLIPSOID && m->geom_type[g1] != mjGEOM_SPHERE
      && m->geom_type[g2] != mjGEOM_ELLIPSOID && m->geom_type[g2] != mjGEOM_SPHERE) {
    // multiCCD parameters
    const mjtNum relative_tolerance = 1e-3;
    const mjtNum perturbation_angle = 1e-3;

    // save positions and orientations of g1 and g2
    mjtNum xpos1[3], xmat1[9], xpos2[3], xmat2[9];
    mju_copy3(xpos1, d->geom_xpos+3*g1);
    mju_copy(xmat1, d->geom_xmat+9*g1, 9);
    mju_copy3(xpos2, d->geom_xpos+3*g2);
    mju_copy(xmat2, d->geom_xmat+9*g2, 9);

    // complete frame of initial contact
    mjtNum frame[9];
    mju_copy(frame, con[0].frame, 9);
    mju_makeFrame(frame);

    // tolerance for determining if newly found contacts are distinct
    const mjtNum tolerance = relative_tolerance * mju_min(m->geom_rbound[g1], m->geom_rbound[g2]);

    // axes and rotation angles for perturbation test
    mjtNum* axes[2] = {frame+3, frame+6};
    mjtNum angles[2] = {-perturbation_angle, perturbation_angle};

    // rotate both geoms, search for new contacts
    for (int axis_id = 0; axis_id < 2; ++axis_id) {
      for (int angle_id = 0; angle_id < 2; ++angle_id) {
        mjtNum* axis = axes[axis_id];
        mjtNum angle = angles[angle_id];

        // make rotation matrix rot
        mjtNum quat[4], rot[9];
        mju_axisAngle2Quat(quat, axis, angle);
        mju_quat2Mat(rot, quat);

        // rotate g1 around initial contact point
        mju_rotateFrame(con[0].pos, rot, d->geom_xmat+9*g1, d->geom_xpos+3*g1);

        // inversely rotate g2 around initial contact point
        mjtNum invrot[9];
        mju_transpose(invrot, rot, 3, 3);
        mju_rotateFrame(con[0].pos, invrot, d->geom_xmat+9*g2, d->geom_xpos+3*g2);

        // search for new contact
        int new_contact = mjc_MPRIteration(&obj1, &obj2, &ccd, m, d, con+ncon, g1, g2, margin);

        // check new contact
        if (new_contact && mjc_isDistinctContact(con, ncon + 1, tolerance)) {
          // set penetration of new point to equal that of initial point
          con[ncon].dist = con[0].dist;
          // add new point
          ncon += 1;
        }

        // reset positions and orientations of g1 and g2
        mju_copy3(d->geom_xpos+3*g1, xpos1);
        mju_copy(d->geom_xmat+9*g1, xmat1, 9);
        mju_copy3(d->geom_xpos+3*g2, xpos2);
        mju_copy(d->geom_xmat+9*g2, xmat2, 9);
      }
    }
  }
#if LIBERO_NATIVE_SUPPORT_REUSE_DIAGNOSTIC
  // Private probe-only words; the default production diagnostic ABI is intact.
  m->adapter_diag[8]=obj1.support_reuse.hits+obj2.support_reuse.hits;
  m->adapter_diag[9]=obj1.support_reuse.misses+obj2.support_reuse.misses;
#endif
  return ncon;
}
struct NativeBoxAxis { double depth,length,dot,normal[3]; };
static __device__ __forceinline__ NativeBoxAxis native_box_axis(
    int axis,const double* pos21,const double* pos12,const double* size1,const double* size2,
    const double* plen1,const double* plen2,const double* rott,const double* rotabs){
  NativeBoxAxis result={0,0,0,{0,0,0}};
  if(axis<6){
    const int i=axis/2;
    result.depth=(axis&1)?-fabs(pos12[i])+size2[i]+plen1[i]:-fabs(pos21[i])+size1[i]+plen2[i];
    return result;
  }
  const int i=(axis-6)/3,j=(axis-6)%3;
  if(i==0){result.normal[1]=-rott[3*j+2];result.normal[2]=+rott[3*j+1];}
  else if(i==1){result.normal[0]=+rott[3*j+2];result.normal[2]=-rott[3*j];}
  else{result.normal[0]=-rott[3*j+1];result.normal[1]=+rott[3*j];}
  result.length=mju_normalize3(result.normal);
  if(result.length<mjMINVAL)return result;
  result.dot=mju_dot3(pos21,result.normal);
  for(int k=0;k<3;++k)if(k!=i)result.depth+=size1[k]*fabs(result.normal[k]);
  for(int k=0;k<3;++k)if(k!=j)result.depth+=size2[k]*rotabs[3*i+3-k-j]/result.length;
  result.depth-=fabs(result.dot);return result;
}
__device__ int mjc_BoxBox(const mjModel* M, const mjData* D, mjContact* con, int g1, int g2, mjtNum margin)
{
  const mjtNum* pos1 = D->geom_xpos + 3 * g1;
  const mjtNum* mat1 = D->geom_xmat + 9 * g1;
  const mjtNum* size1 = M->geom_size + 3 * g1;
  const mjtNum* pos2 = D->geom_xpos + 3 * g2;
  const mjtNum* mat2 = D->geom_xmat + 9 * g2;
  const mjtNum* size2 = M->geom_size + 3 * g2;

  mjtNum pos12[3], pos21[3], rot[9], rott[9], rotabs[9], rottabs[9], tmp1[3], tmp2[3], plen1[3],
         plen2[3];
  mjtNum rotmore[9], p[3], r[9], s[3], ss[3], lp[3], rt[9], points[mjMAXCONPAIR][3],
         depth[mjMAXCONPAIR], pts[6][3], ppts2[4][2], pu[4][3], axi[3][3];
  mjtNum linesu[4][6], lines[4][6], clnorm[3], rnorm[3];
  mjtNum penetration, c1, c2, c3, a, b, c, d, lx, ly, hz, l, x, y, u, v, llx, lly, innorm, margin2;

  int i0, i1, i2;
  mjtNum f0, f1, f2;

  int i, j, q, code, q1, q2, clcorner, n, m, k;
  int cle1, cle2, in, ax1, ax2, pax1, pax2, clface, nl, nf;

  n = 0;
  code = -1;
  margin2 = margin * margin;

  mju_sub3(tmp1, pos2, pos1);
  mju_rotVecMatT(pos21, tmp1, mat1);

  mju_sub3(tmp1, pos1, pos2);
  mju_rotVecMatT(pos12, tmp1, mat2);

  mju_mulMatTMat(rot, mat1, mat2, 3, 3, 3);
  mju_transpose(rott, rot, 3, 3);

  for (i = 0; i < 9; i++)
    rotabs[i] = fabs(rot[i]);
  for (i = 0; i < 9; i++)
    rottabs[i] = fabs(rott[i]);

  mju_rotVecMat(plen2, size2, rotabs);
  mju_rotVecMatT(plen1, size1, rotabs);

  for (i = 0, penetration = margin; i < 3; i++)
    penetration += size1[i] * 3 + size2[i] * 3;

  if(M->adapter_subgroup_width==8 || M->adapter_subgroup_width==16 || M->adapter_subgroup_width==32){
    const int width=M->adapter_subgroup_width,lane=int(threadIdx.x)&(width-1);
    const unsigned mask=native_query_mask(width);
    NativeBoxAxis local[2];
    for(int slot=0;slot<2;++slot){
      const int axis=lane+slot*width;
      if(axis<15)local[slot]=native_box_axis(axis,pos21,pos12,size1,size2,plen1,plen2,rott,rotabs);
      else local[slot]={0,0,0,{0,0,0}};
    }
    // Evaluate axes independently, then replay every decision in the exact
    // face-pair / edge-axis order. Threshold-dependent best-axis ties remain
    // sequential; clipping below is unchanged and uses private query state.
    for(int axis=0;axis<15;++axis){
      const NativeBoxAxis& own=local[axis/width];const int owner=axis%width;
      const double depth_axis=__shfl_sync(mask,own.depth,owner,width);
      const double axis_length=__shfl_sync(mask,own.length,owner,width);
      const double axis_dot=__shfl_sync(mask,own.dot,owner,width);
      double normal[3];for(int k=0;k<3;++k)normal[k]=__shfl_sync(mask,own.normal[k],owner,width);
      if(axis<6){
        // The original code checks both faces before updating either one.
        if((axis&1)==0){
          const int other_owner=(axis+1)%width;
          const NativeBoxAxis& other=local[(axis+1)/width];
          const double other_depth=__shfl_sync(mask,other.depth,other_owner,width);
          if(depth_axis<-margin || other_depth<-margin)return 0;
        }
        i=axis/2;
        if(depth_axis<penetration){penetration=depth_axis;
          code=(axis&1)?i+3*(pos12[i]<0)+6:i+3*(pos21[i]<0);}
      }else{
        i=(axis-6)/3;j=(axis-6)%3;
        if(axis_length<mjMINVAL)continue;
        if(depth_axis<-margin)return 0;
        if(depth_axis<penetration*(1-1e-12)){
          penetration=depth_axis;
          for(k=cle1=0;k<3;++k)if(k!=i)if((normal[k]>0)^(axis_dot<0))cle1+=1<<k;
          for(k=cle2=0;k<3;++k)if(k!=j)
            if((rot[3*i+3-k-j]>0)^(axis_dot<0)^((k-j+3)%3==1))cle2+=1<<k;
          code=12+i*3+j;mju_copy3(clnorm,normal);in=axis_dot<0;
        }
      }
    }
  }else{
  for (i = 0; i < 3; i++) {
    c1 = -fabs(pos21[i]) + size1[i] + plen2[i];
    c2 = -fabs(pos12[i]) + size2[i] + plen1[i];

    if (c1 < -margin || c2 < -margin)
      return 0;

    if (c1 < penetration) {
      penetration = c1;
      code = i + 3 * (pos21[i] < 0) + 0;
    }
    if (c2 < penetration) {
      penetration = c2;
      code = i + 3 * (pos12[i] < 0) + 6;
    }

    // printf("%24.16e %24.16e %d         %24.16e %d \n",c1,c2,i,penetration,code);
  }

  for (i = 0; i < 3; i++) {
    for (j = 0; j < 3; j++) {
      mju_zero3(tmp2);
      if (i == 0) {
        tmp2[1] = -rott[3 * j + 2];
        tmp2[2] = +rott[3 * j + 1];
      } else if (i == 1) {
        tmp2[0] = +rott[3 * j + 2];
        tmp2[2] = -rott[3 * j + 0];
      } else if (i == 2) {
        tmp2[0] = -rott[3 * j + 1];
        tmp2[1] = +rott[3 * j + 0];
      }

      c1 = mju_normalize3(tmp2);


      if (c1 < mjMINVAL)
        continue;

      c2 = mju_dot3(pos21, tmp2);

      c3 = 0;

      for (k = 0; k < 3; k++)
        if (k != i)
          c3 += size1[k] * fabs(tmp2[k]);
      for (k = 0; k < 3; k++)
        if (k != j)
          c3 += size2[k] * rotabs[3 * i + 3 - k - j] / c1;

      c3 -= fabs(c2);

      if (c3 < -margin)
        return 0;



      if (c3 < penetration * (1 - 1e-12))
      {
        penetration = c3;
        for (k = cle1 = 0; k < 3; k++)
          if (k != i)
            if ((tmp2[k] > 0) ^ (c2 < 0))
              cle1 += 1 << k;
        for (k = cle2 = 0; k < 3; k++)
          if (k != j)
            if ((rot[3 * i + 3 - k - j] > 0) ^ (c2 < 0) ^ ((k - j + 3) % 3 == 1))
              cle2 += 1 << k;

        code = 12 + i * 3 + j;
        mju_copy3(clnorm, tmp2);
        in = c2 < 0;
      }

      // printf("%24.16e %d      %24.16e %d\n",c3,12+i*3+j,penetration,code);
    }
  }


  } // scalar SAT remains available for independent per-lane queries
  // return 0;


  // printf("%d\n",code);

  M->adapter_diag[6]=code;
  if (code == -1)
    return 0;  // shouldn't happen

  if (code >= 12)
    goto edgeedge;


  q1 = code % 6;
  q2 = code / 6;

  // printf("%d %d\n",q1,q2);

  mju_zero(rotmore, 9);
  if (q1 == 0)
    rotmore[2] = -1, rotmore[4] = +1, rotmore[6] = +1;
  else if (q1 == 1)
    rotmore[0] = +1, rotmore[5] = -1, rotmore[7] = +1;
  else if (q1 == 2)
    rotmore[0] = +1, rotmore[4] = +1, rotmore[8] = +1;
  else if (q1 == 3)
    rotmore[2] = +1, rotmore[4] = +1, rotmore[6] = -1;
  else if (q1 == 4)
    rotmore[0] = +1, rotmore[5] = +1, rotmore[7] = -1;
  else if (q1 == 5)
    rotmore[0] = -1, rotmore[4] = +1, rotmore[8] = -1;

  i0 = 0;
  i1 = 1;
  i2 = 2;
  f0 = f1 = f2 = 1;

  if (q1 == 0) {
    i0 = 2;
    f0 = -1;
    i2 = 0;
  } else if (q1 == 1) {
    i1 = 2;
    f1 = -1;
    i2 = 1;
  } else if (q1 == 2) {
  } else if (q1 == 3) {
    i0 = 2;
    i2 = 0;
    f2 = -1;
  } else if (q1 == 4) {
    i1 = 2;
    i2 = 1;
    f2 = -1;
  } else if (q1 == 5) {
    f0 = -1;
    f2 = -1;
  }


#define rotaxis(vecres, vecin) \
{                              \
  vecres[0]=vecin[i0]*f0;      \
  vecres[1]=vecin[i1]*f1;      \
  vecres[2]=vecin[i2]*f2;      \
}
#define rotmatx(matres, matin)        \
{                                     \
  mju_scl3(matres+0, matin+i0*3, f0); \
  mju_scl3(matres+3, matin+i1*3, f1); \
  mju_scl3(matres+6, matin+i2*3, f2); \
}

  if (q2) {
    mju_mulMatMatT(r, rotmore, rot, 3, 3, 3);

    // mju_rotVecMat(p,pos12,rotmore);
    // mju_rotVecMat(tmp1,size2,rotmore);

    rotaxis(p, pos12);
    rotaxis(tmp1, size2);

    mju_copy3(s, size1);
  } else {
    // mju_mulMatMat(r,rotmore,rot,3,3,3);

    rotmatx(r, rot);

    // mju_rotVecMat(p,pos21,rotmore);
    // mju_rotVecMat(tmp1,size1,rotmore);

    rotaxis(p, pos21);
    rotaxis(tmp1, size1);

    mju_copy3(s, size2);
  }

  mju_transpose(rt, r, 3, 3);

  for (i = 0; i < 3; i++)
    ss[i] = mju_abs(tmp1[i]);

  lx = ss[0];
  ly = ss[1];
  hz = ss[2];
  p[2] -= hz;

  mju_copy3(lp, p);

  for (clcorner = 0, i = 0; i < 3; i++)
    if (r[6 + i] < 0)
      clcorner += 1 << i;

  mju_addToScl3(lp, rt + 0, s[0] * ((clcorner & 1) ? 1 : -1));
  mju_addToScl3(lp, rt + 3, s[1] * ((clcorner & 2) ? 1 : -1));
  mju_addToScl3(lp, rt + 6, s[2] * ((clcorner & 4) ? 1 : -1));

  m = k = 0;
  mju_copy3(pts[m++], lp);

  for (i = 0; i < 3; i++)
    if (fabs(r[6 + i]) < 0.5)
      mju_scl3(pts[m++], rt + 3 * i, s[i] * ((clcorner & (1 << i)) ? -2 : 2));

  mju_add3(pts[3], pts[0], pts[1]);
  mju_add3(pts[4], pts[0], pts[2]);
  mju_add3(pts[5], pts[3], pts[2]);

  if (m > 1)
  {
    mju_copy3(lines[k] + 0, pts[0]);
    mju_copy3(lines[k++] + 3, pts[1]);
  }
  if (m > 2)
  {
    mju_copy3(lines[k] + 0, pts[0]);
    mju_copy3(lines[k++] + 3, pts[2]);
    mju_copy3(lines[k] + 0, pts[3]);
    mju_copy3(lines[k++] + 3, pts[2]);
    mju_copy3(lines[k] + 0, pts[4]);
    mju_copy3(lines[k++] + 3, pts[1]);
  }

  for (i = 0; i < k; i++) {
    for (q = 0; q < 2; q++) {
      a = lines[i][0 + q];
      b = lines[i][3 + q];
      c = lines[i][1 - q];
      d = lines[i][4 - q];

      if (fabs(b) > mjMINVAL) {
        for (j = -1; j <= 1; j += 2) {
          l = ss[q] * j;
          c1 = (l - a) * (1 / b);
          if (c1 < 0 || c1 > 1)
            continue;
          c2 = c + d * c1;
          if (fabs(c2) > ss[1 - q])
            continue;

          mju_copy3(points[n], lines[i]);
          mju_addToScl3(points[n++], lines[i] + 3, c1);
        }
      }
    }
  }


  a = pts[1][0];
  b = pts[2][0];
  c = pts[1][1];
  d = pts[2][1];
  c1 = a * d - b * c;


  if (m > 2) {
    for (i = 0; i < 4; i++) {
      llx = i / 2 ? lx : -lx;
      lly = i % 2 ? ly : -ly;

      x = llx - pts[0][0];
      y = lly - pts[0][1];

      u = (x * d - y * b) * (1 / c1);
      v = (y * a - x * c) * (1 / c1);
      if (u <= 0 || v <= 0 || u >= 1 || v >= 1)
        continue;

      points[n][0] = llx;
      points[n][1] = lly;
      points[n][2] = (pts[0][2] + u * pts[1][2] + v * pts[2][2]);
      n++;
    }
  }

  for (i = 0; i < (1 << (m - 1)); i++) {
    mju_copy3(tmp1, pts[i == 0 ? 0 : i + 2]);


    if (i)
      if (tmp1[0] <= -lx || tmp1[0] >= lx)
        continue;
    if (i)
      if (tmp1[1] <= -ly || tmp1[1] >= ly)
        continue;

    mju_copy3(points[n++], tmp1);
  }


  m = n;
  n = 0;

  for (i = 0; i < m; i++)
  {
    if (points[i][2] > margin)
      continue;
    mju_copy3(points[n], points[i]);

    depth[n] = points[n][2];
    points[n][2] *= 0.5;

    n++;
  }


  mju_mulMatMatT(r, q2 ? mat2 : mat1, rotmore, 3, 3, 3);
  mju_copy3(p, q2 ? pos2 : pos1);

  tmp2[0] = (q2 ? -1 : 1) * r[2];
  tmp2[1] = (q2 ? -1 : 1) * r[5];
  tmp2[2] = (q2 ? -1 : 1) * r[8];

  *M->adapter_frame0=1;
  mju_copy3(con[0].frame, tmp2);
  mju_zero3(con[0].frame + 3);




  for (i = 0; i < n; i++)
  {
    con[i].dist = points[i][2];
    points[i][2] += hz;

    mju_rotVecMat(tmp2, points[i], r);
    mju_add3(con[i].pos, tmp2, p);

    if (i)
      mju_copy(con[i].frame, con[0].frame, 6);
  }


  // printf("Path1:  %d\n",n);


  return n;

edgeedge:


  code -= 12;

  q1 = code / 3;
  q2 = code % 3;



  if (q2 == 0)
    ax1 = 1, ax2 = 2;
  if (q2 == 1)
    ax1 = 0, ax2 = 2;
  if (q2 == 2)
    ax1 = 1, ax2 = 0;
  if (q1 == 0)
    pax1 = 1, pax2 = 2;
  if (q1 == 1)
    pax1 = 0, pax2 = 2;
  if (q1 == 2)
    pax1 = 1, pax2 = 0;

  // printf("%lf %lf   %lf %lf\n",rot[ 3*q1+ ax1],rot [3*q1+ ax2],rott[3*q2+pax1],rott[3*q2+pax2]);
  // printf("%lf %lf\n",mju_dot3(clnorm,rott+3*ax1),mju_dot3(clnorm,rott+3*ax2));

  if (rotabs [3 * q1 + ax1] < rotabs [3 * q1 + ax2]) {
    ax1 = ax2;
    ax2 = 3 - q2 - ax1;
  }
  if (rottabs[3 * q2 + pax1] < rottabs[3 * q2 + pax2]) {
    pax1 = pax2;
    pax2 = 3 - q1 - pax1;
  }

  if (cle1 & (1 << pax2))
    clface = pax2;
  else
    clface = pax2 + 3;


  // printf("%lf - %d %d %d %d   %d %d     %d %d %d %d %d\n",
  //        penetration,cle1,cle2,code,in,q1,q2,clface,ax1,ax2,pax1,pax2);


  mju_zero(rotmore, 9);
  if (clface == 0)
    rotmore[2] = -1, rotmore[4] = +1, rotmore[6] = +1;
  else if (clface == 1)
    rotmore[0] = +1, rotmore[5] = -1, rotmore[7] = +1;
  else if (clface == 2)
    rotmore[0] = +1, rotmore[4] = +1, rotmore[8] = +1;
  else if (clface == 3)
    rotmore[2] = +1, rotmore[4] = +1, rotmore[6] = -1;
  else if (clface == 4)
    rotmore[0] = +1, rotmore[5] = +1, rotmore[7] = -1;
  else if (clface == 5)
    rotmore[0] = -1, rotmore[4] = +1, rotmore[8] = -1;


  i0 = 0;
  i1 = 1;
  i2 = 2;
  f0 = f1 = f2 = 1;

  if (clface == 0) {
    i0 = 2;
    f0 = -1;
    i2 = 0;
  } else if (clface == 1) {
    i1 = 2;
    f1 = -1;
    i2 = 1;
  } else if (clface == 2) {
  } else if (clface == 3) {
    i0 = 2;
    i2 = 0;
    f2 = -1;
  } else if (clface == 4) {
    i1 = 2;
    i2 = 1;
    f2 = -1;
  } else if (clface == 5) {
    f0 = -1;
    f2 = -1;
  }

  // mju_rotVecMat(p,pos21,rotmore);
  // mju_rotVecMat(rnorm,clnorm,rotmore);
  rotaxis(p, pos21);
  rotaxis(rnorm, clnorm);

  // print("rnorm",rnorm);

  // mju_mulMatMat(r,rotmore,rot,3,3,3);
  rotmatx(r, rot);

  mju_rotVecMatT(tmp1, size1, rotmore);
  for (i = 0; i < 3; i++)
    s[i] = mju_abs(tmp1[i]);

  mju_transpose(rt, r, 3, 3);


  lx = s[0];
  ly = s[1];
  hz = s[2];
  p[2] -= hz;


  n = 0;
  mju_copy3(points[n], p);
  mju_addToScl3(points[n], rt + 3 * ax1, size2[ax1] * ((cle2 & (1 << ax1)) ? 1 : -1));
  mju_addToScl3(points[n], rt + 3 * ax2, size2[ax2] * ((cle2 & (1 << ax2)) ? 1 : -1));
  mju_copy3(points[n + 1], points[n]);
  mju_addToScl3(points[n], rt + 3 * q2, size2[q2]);
  n = 1;
  mju_addToScl3(points[n], rt + 3 * q2, -size2[q2]);
  n = 2;


  mju_copy3(points[n], p);
  mju_addToScl3(points[n], rt + 3 * ax1, size2[ax1] * ((cle2 & (1 << ax1)) ? -1 : 1));
  mju_addToScl3(points[n], rt + 3 * ax2, size2[ax2] * ((cle2 & (1 << ax2)) ? 1 : -1));
  mju_copy3(points[n + 1], points[n]);
  mju_addToScl3(points[n], rt + 3 * q2, size2[q2]);
  n = 3;
  mju_addToScl3(points[n], rt + 3 * q2, -size2[q2]);
  n = 4;


  mju_copy3(axi[0], points[0]);
  mju_sub3(axi[1], points[1], points[0]);
  mju_sub3(axi[2], points[2], points[0]);


  if (fabs(rnorm[2]) < mjMINVAL)
    return 0;  // shouldn't happen

  innorm = (1 / rnorm[2]) * (in ? -1 : 1);
  // printf("%lf\n",innorm);

  for (i = 0; i < 4; i++)
  {
    c1 = -points[i][2] * (1 / rnorm[2]);

    mju_copy3(pu[i], points[i]);

    mju_addToScl3(points[i], rnorm, c1);

    // ppts[i][0]=points[i][0];
    // ppts[i][1]=points[i][1];
    ppts2[i][0] = points[i][0];
    ppts2[i][1] = points[i][1];
  }


  mju_copy3(pts[0], points[0]);
  mju_sub3(pts[1], points[1], points[0]);
  mju_sub3(pts[2], points[2], points[0]);

  m = 3;
  k = 0;
  n = 0;


  if (m > 1) {
    mju_copy3(lines[k] + 0, pts[0]);
    mju_copy3(lines[k] + 3, pts[1]);
    mju_copy3(linesu[k] + 0, axi[0]);
    mju_copy3(linesu[k++] + 3, axi[1]);
  }
  if (m > 2) {
    mju_copy3(lines[k] + 0, pts[0]);
    mju_copy3(lines[k] + 3, pts[2]);
    mju_copy3(linesu[k] + 0, axi[0]);
    mju_copy3(linesu[k++] + 3, axi[2]);

    mju_add3(lines[k] + 0, pts[0], pts[1]);
    mju_copy3(lines[k] + 3, pts[2]);
    mju_add3(linesu[k] + 0, axi[0], axi[1]);
    mju_copy3(linesu[k++] + 3, axi[2]);

    mju_add3(lines[k] + 0, pts[0], pts[2]);
    mju_copy3(lines[k] + 3, pts[1]);
    mju_add3(linesu[k] + 0, axi[0], axi[2]);
    mju_copy3(linesu[k++] + 3, axi[1]);
  }

  for (i = 0; i < k; i++) {
    for (q = 0; q < 2; q++) {
      a = lines[i][0 + q];
      b = lines[i][3 + q];
      c = lines[i][1 - q];
      d = lines[i][4 - q];

      if (fabs(b) > mjMINVAL) {
        for (j = -1; j <= 1; j += 2) {
          if (n < mjMAXCONPAIR) {
            l = s[q] * j;
            c1 = (l - a) * (1 / b);
            if (c1 < 0 || c1 > 1)
              continue;
            c2 = c + d * c1;
            if (fabs(c2) > s[1 - q])
              continue;

            if ((linesu[i][2] + linesu[i][5]*c1)*innorm > margin)
              continue;

            mju_scl3(points[n], linesu[i], 0.5);
            mju_addToScl3(points[n], linesu[i] + 3, 0.5 * c1);
            points[n][0 + q] += 0.5 * l;
            points[n][1 - q] += 0.5 * c2;
            depth[n] = points[n][2] * innorm * 2;
            n++;
          }
        }
      }
    }
  }

  nl = n;

  a = pts[1][0];
  b = pts[2][0];
  c = pts[1][1];
  d = pts[2][1];
  c1 = a * d - b * c;

  for (i = 0; i < 4; i++) {
    if (n < mjMAXCONPAIR) {
      llx = i / 2 ? lx : -lx;
      lly = i % 2 ? ly : -ly;

      x = llx - pts[0][0];
      y = lly - pts[0][1];

      u = (x * d - y * b) * (1 / c1);
      v = (y * a - x * c) * (1 / c1);

      const int outside = u < 0 || u > 1 || v < 0 || v > 1;
      if (nl == 0) {
        if ((u < 0 || u > 1) && (v < 0 || v > 1))
          continue;
      } else {
        if ((u < 0 || u > 1 || v < 0 || v > 1))
          continue;
      }

      if (u < 0)
        u = 0;
      if (u > 1)
        u = 1;
      if (v < 0)
        v = 0;
      if (v > 1)
        v = 1;


      mju_scl3(tmp1, pu[0], 1 - u - v);
      mju_addToScl3(tmp1, pu[1], u);
      mju_addToScl3(tmp1, pu[2], v);

      points[n][0] = llx;
      points[n][1] = lly;
      points[n][2] = 0;

      mju_sub3(tmp2, points[n], tmp1);

      // c1 remains the projection determinant for the next corner.
      c2 = mju_dot3(tmp2, tmp2);
      if (outside || tmp1[2] > 0)
        if (c2 > margin2)
          continue;

      mju_add3(points[n], points[n], tmp1);
      mju_scl3(points[n], points[n], 0.5);

      depth[n] = sqrt(c2) * (!outside && tmp1[2] < 0 ? -1 : 1);
      n++;
    }
  }

  nf = n;

  for (i = 0; i < 4; i++) {
    if (n < mjMAXCONPAIR) {
      x = ppts2[i][0];
      y = ppts2[i][1];
      const int outside = x < -lx || x > lx || y < -ly || y > ly;

      if (nl == 0) {
        if (nf == 0) {
        } else {
          if (x < -lx || x > lx)
            if (y < -ly || y > ly)
              continue;
        }
      } else {
        if (x < -lx || x > lx || y < -ly || y > ly)
          continue;
      }

      for (c1 = 0, j = 0; j < 2; j++)
        if (ppts2[i][j] < -s[j])
          c1 += (ppts2[i][j] + s[j]) * (ppts2[i][j] + s[j]);
        else if (ppts2[i][j] > s[j])
          c1 += (ppts2[i][j] - s[j]) * (ppts2[i][j] - s[j]);

      c1 += pu[i][2] * innorm * pu[i][2] * innorm;

      if (outside || pu[i][2] > 0)
        if (c1 > margin2)
          continue;


      tmp1[0] = ppts2[i][0] * 0.5;
      tmp1[1] = ppts2[i][1] * 0.5;
      tmp1[2] = 0;

      for (j = 0; j < 2; j++) {
        if (ppts2[i][j] < -s[j])
          tmp1[j] = -s[j] * 0.5;
        else if (ppts2[i][j] > s[j])
          tmp1[j] = +s[j] * 0.5;
      }
      mju_addToScl3(tmp1, pu[i], 0.5);
      mju_copy3(points[n], tmp1);

      depth[n] = sqrt(c1) * (!outside && pu[i][2] < 0 ? -1 : 1);
      n++;
    }
  }

  mju_mulMatMatT(r, mat1, rotmore, 3, 3, 3);

  mju_rotVecMat(tmp1, rnorm, r);

  *M->adapter_frame0=1;
  mju_scl3(con[0].frame, tmp1, in ? -1 : 1);
  mju_zero3(con[0].frame + 3);


  for (i = 0; i < n; i++) {
    con[i].dist = depth[i];
    points[i][2] += hz;

    mju_rotVecMat(tmp2, points[i], r);

    mju_add3(con[i].pos, tmp2, pos1);

    mju_copy(con[i].frame, con[0].frame, 6);
  }

  return n;

#undef rotaxis
#undef rotmatx
}
